'use strict';

class InvalidTransitionError extends Error {
  constructor(from, to, order_id) {
    super(`Invalid transition: ${from} → ${to} for order ${order_id}`);
    this.from = from; this.to = to; this.order_id = order_id;
    this.name = 'InvalidTransitionError';
  }
}

/** Existing — flat switch. KEEP behaviour intact while refactoring. */
function transition(order, to) {
  const from = order.status;
  switch (from) {
    case 'pending':
      if (to === 'paid') return { ...order, status: 'paid' };
      if (to === 'cancelled') return { ...order, status: 'cancelled' };
      break;
    case 'paid':
      if (to === 'shipped') return { ...order, status: 'shipped' };
      if (to === 'cancelled') return { ...order, status: 'cancelled' };
      break;
    case 'shipped':
      if (to === 'delivered') return { ...order, status: 'delivered' };
      break;
    case 'delivered':
    case 'refunded':
    case 'cancelled':
      break;
  }
  throw new InvalidTransitionError(from, to, order.order_id);
}

// TODO: applyPartialRefund + applyChargeback go here. The table-driven
// rewrite of transition() goes here. Keep InvalidTransitionError exported.

module.exports = { transition, InvalidTransitionError };

const { transition, InvalidTransitionError } = require('../src/orderState');

const base = { order_id: 'o1', amount: 100, refunded_total: 0, status: 'pending' };

test('pending → paid', () => {
  expect(transition(base, 'paid').status).toBe('paid');
});
test('pending → cancelled', () => {
  expect(transition(base, 'cancelled').status).toBe('cancelled');
});
test('paid → shipped', () => {
  expect(transition({ ...base, status: 'paid' }, 'shipped').status).toBe('shipped');
});
test('shipped → delivered', () => {
  expect(transition({ ...base, status: 'shipped' }, 'delivered').status).toBe('delivered');
});
test('terminal states reject', () => {
  expect(() => transition({ ...base, status: 'delivered' }, 'paid')).toThrow(InvalidTransitionError);
});
test('illegal transition throws with order_id', () => {
  try { transition({ ...base, status: 'pending' }, 'shipped'); }
  catch (e) { expect(e.order_id).toBe('o1'); expect(e.from).toBe('pending'); }
});

'use strict';

class InvalidTransitionError extends Error {
  constructor(from, to, order_id) {
    super(`Invalid transition: ${from} → ${to} for order ${order_id}`);
    this.from = from; this.to = to; this.order_id = order_id;
    this.name = 'InvalidTransitionError';
  }
}

// Data-driven transition table. Edges are sets so order doesn't matter.
const EDGES = {
  pending:         new Set(['paid', 'cancelled']),
  paid:            new Set(['shipped', 'cancelled', 'disputed']),
  shipped:         new Set(['delivered', 'disputed']),
  delivered:       new Set(['disputed']),
  disputed:        new Set(['chargeback_won', 'chargeback_lost']),
  chargeback_won:  new Set([]),   // re-enters via applyChargebackWon to PRIOR state
  chargeback_lost: new Set([]),
  refunded:        new Set([]),
  cancelled:       new Set([]),
};

function transition(order, to) {
  const from = order.status;
  const allowed = EDGES[from];
  if (!allowed || !allowed.has(to)) throw new InvalidTransitionError(from, to, order.order_id);
  return { ...order, status: to };
}

/**
 * Accumulate a partial refund. Stays in current state unless the
 * total reaches the order amount, in which case we transition to refunded.
 */
function applyPartialRefund(order, amount) {
  if (typeof amount !== 'number' || amount <= 0) {
    throw new Error('refund amount must be positive');
  }
  const newTotal = (order.refunded_total || 0) + amount;
  if (newTotal > order.amount) {
    throw new Error('refund would exceed order amount');
  }
  const next = { ...order, refunded_total: newTotal };
  if (newTotal === order.amount) return { ...next, status: 'refunded' };
  return next;
}

/**
 * Move to disputed if we're in a post-paid state. Records pre_dispute_status
 * so chargeback_won can return us there.
 */
function applyChargeback(order, reason) {
  if (!['paid', 'shipped', 'delivered'].includes(order.status)) {
    throw new InvalidTransitionError(order.status, 'disputed', order.order_id);
  }
  return { ...order, status: 'disputed', pre_dispute_status: order.status, dispute_reason: reason || 'unspecified' };
}

function applyChargebackWon(order) {
  if (order.status !== 'disputed') throw new InvalidTransitionError(order.status, 'chargeback_won', order.order_id);
  return { ...order, status: order.pre_dispute_status || 'paid', pre_dispute_status: null };
}

function applyChargebackLost(order) {
  if (order.status !== 'disputed') throw new InvalidTransitionError(order.status, 'chargeback_lost', order.order_id);
  return { ...order, status: 'chargeback_lost' };
}

module.exports = {
  transition, applyPartialRefund, applyChargeback, applyChargebackWon, applyChargebackLost,
  InvalidTransitionError, EDGES,
};

