cat > tests/new.test.js <<'EOF'
const { applyPartialRefund, applyChargeback, applyChargebackWon, applyChargebackLost, InvalidTransitionError, EDGES } = require('../src/orderState');

const base = { order_id: 'o2', amount: 100, refunded_total: 0, status: 'delivered' };

test('partial refund accumulates, stays in current state', () => {
  let o = applyPartialRefund(base, 30);
  expect(o.status).toBe('delivered');
  expect(o.refunded_total).toBe(30);
  o = applyPartialRefund(o, 20);
  expect(o.refunded_total).toBe(50);
  expect(o.status).toBe('delivered');
});

test('refund reaching amount moves to refunded', () => {
  let o = applyPartialRefund(base, 70);
  o = applyPartialRefund(o, 30);
  expect(o.status).toBe('refunded');
});

test('chargeback from paid → disputed; won returns to paid', () => {
  let o = applyChargeback({ ...base, status: 'paid' }, 'fraud');
  expect(o.status).toBe('disputed');
  expect(o.pre_dispute_status).toBe('paid');
  const back = applyChargebackWon(o);
  expect(back.status).toBe('paid');
});

test('chargeback from pending throws', () => {
  expect(() => applyChargeback({ ...base, status: 'pending' }, 'r')).toThrow(InvalidTransitionError);
});

test('EDGES is a data structure, not inlined', () => {
  expect(typeof EDGES).toBe('object');
  expect(EDGES.paid.has('disputed')).toBe(true);
  expect(EDGES.refunded.size).toBe(0);
});
EOF
npm test --silent

